-- buyer_viewed_properties: tracks which listings a buyer (entity) has viewed.
CREATE TABLE IF NOT EXISTS "panda_realty"."buyer_viewed_properties" (
  "buyer_viewed_property_id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "entity_id"                bigint NOT NULL
    REFERENCES "panda_realty"."entities" ("entity_id") ON DELETE CASCADE,
  "property_list_id"         bigint NOT NULL
    REFERENCES "panda_realty"."panda_properties" ("property_list_id") ON DELETE CASCADE,
  "viewed_at"                timestamp DEFAULT now(),
  "created_at"               timestamp DEFAULT now(),
  "updated_at"               timestamp
);

-- buyer_preferred_features: free-text features a buyer wants in a property.
CREATE TABLE IF NOT EXISTS "panda_realty"."buyer_preferred_features" (
  "buyer_preferred_feature_id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "entity_id"                  bigint NOT NULL
    REFERENCES "panda_realty"."entities" ("entity_id") ON DELETE CASCADE,
  "feature"                    citext NOT NULL,
  "created_at"                 timestamp DEFAULT now(),
  "updated_at"                 timestamp
);
